WITH filtered_subscriptions AS (SELECT *, TRIM(status) AS clean_status FROM subscriptions WHERE plan IN ('premium', 'basic', 'standard') AND status NOT IN ('CANCELLED', 'PAUSED')), subscriptions_stats AS (SELECT CASE WHEN monthly_fee >= 246 THEN 'high' WHEN monthly_fee >= 67 THEN 'mid' ELSE 'low' END AS monthly_fee_bucket, COUNT(DISTINCT monthly_fee) AS unique_statuss FROM filtered_subscriptions GROUP BY CASE WHEN monthly_fee >= 246 THEN 'high' WHEN monthly_fee >= 67 THEN 'mid' ELSE 'low' END) SELECT * FROM subscriptions_stats;
